'use strict';
// A per-launch shutdown request is deliberately separate from the generic server API.
// The secret is generated by StartHeroTavern.ps1 and never sent to the browser.
const fs=require('node:fs'),path=require('node:path');
function requestExit(root,secret){
 if(!/^[0-9a-f]{32}$/i.test(String(secret||'')))throw Error('The managed Hero Tavern launcher is unavailable. Stop the session using its launcher window.');
 const dir=path.join(root,'Run');
 fs.mkdirSync(dir,{recursive:true});
 const dest=path.join(dir,'exit-'+secret+'.request');
 fs.writeFileSync(dest,JSON.stringify({requestedAt:new Date().toISOString(),kind:'graceful-exit'}),{flag:'w'});
 return {requested:true,message:'Hero Tavern is stopping its managed servers. Wait for the launcher to close.'};
}
module.exports={requestExit};
